            // начало модификации
            $product_ids = array_keys($results); //получаем все категории которые относятся к текущему списку продуктов
            $query = $this->db->query("WITH RECURSIVE category_tree AS (
    SELECT
        ptc.category_id as original_category_id,
        ptc.category_id as category_id,
        c.parent_id
    FROM oc_product_to_category ptc
    JOIN oc_category c ON c.category_id = ptc.category_id and ptc.product_id IN (".implode(', ',$product_ids).")

    UNION ALL

    SELECT
        ct.original_category_id,
        c.category_id as category_id,
        c.parent_id
    FROM category_tree ct
    JOIN oc_category c ON c.category_id = ct.parent_id
)
SELECT DISTINCT
    category_id
FROM category_tree");
            $query->rows;
            $this->load->model('catalog/category');
            $this->data['categories'] = array();
            $categories_ids = array_column($query->rows, 'category_id'); //да можно добавить разные проверки существование и прочее, но пока так
            $categories = $this->model_catalog_category->getCategories(0);
            foreach ($categories as $category) {
                if (in_array($category['category_id'], $categories_ids)) {
                    $this->data['categories'][] = array(
                        'category_id' => $category['category_id'],
                        'name'        => $category['name'],
                        'href'        => $this->url->link('product/special', 'filter_category_id=' . $category['category_id']), //забивать в лоб url в целом плохая идея, но для тестового сойдет
                        'remove_href' => $this->url->link('product/special') // URL при снятии
                    );
                }
            }
            // Передать идентификатор текущей выбранной категории в шаблон
            $this->data['filter_category_id'] = $category_id;
